def transform(grid):
    if not grid or not grid[0]:
        return []

    height, width = len(grid), len(grid[0])

    # Find horizontal separator row
    row_idx = None
    sep_color = None
    for r in range(height):
        if len(set(grid[r])) == 1:
            sep_color = grid[r][0]
            row_idx = r
            break

    # Find vertical separator column
    col_idx = None
    if row_idx is not None and sep_color is not None:
        for c in range(width):
            if all(grid[r][c] == sep_color for r in range(height)):
                col_idx = c
                break

    if row_idx is None or col_idx is None:
        return grid

    # Extract the four quadrants
    tl = [row[:col_idx] for row in grid[:row_idx]]
    tr = [row[col_idx+1:] for row in grid[:row_idx]]
    bl = [row[:col_idx] for row in grid[row_idx+1:]]
    br = [row[col_idx+1:] for row in grid[row_idx+1:]]

    def rotate_180(q):
        if not q or not q[0]:
            return []
        return [row[::-1] for row in q[::-1]]

    # Swap quadrants diagonally with 180° rotation
    # BL -> TL position, BR -> TR position, TR -> BL position, TL -> BR position
    output_tl = rotate_180(bl)
    output_tr = rotate_180(br)
    output_bl = rotate_180(tr)
    output_br = rotate_180(tl)

    # Build output: top half from BL+BR rotated, bottom half from TR+TL rotated
    output = []
    num_rows = max(len(output_tl), len(output_bl))

    for r in range(num_rows):
        if r < len(output_tl) and r < len(output_tr):
            output.append(output_tl[r] + output_tr[r])
        elif r < len(output_tl):
            output.append(output_tl[r])
        else:
            output.append(output_bl[r])

    num_rows2 = max(len(output_bl), len(output_br))
    for r in range(num_rows2):
        if r < len(output_bl) and r < len(output_br):
            output.append(output_bl[r] + output_br[r])
        elif r < len(output_bl):
            output.append(output_bl[r])
        else:
            output.append(output_br[r])

    return output
